'use client';

import { useEffect, useMemo, useState } from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './node-pulse-graph.css';

export interface GraphNode {
  id: string;
  label: string;
  x: number;
  y: number;
}

export interface NodePulseGraphProps {
  nodes: GraphNode[];
  edges: [string, string][];
  /** The node the pulse starts from. */
  source: string;
  /** Change this value to send a new pulse. */
  run: number;
  /** Called with the nodes reached at each step, for a text summary. */
  onComplete?: (levels: string[][]) => void;
  viewBox: string;
  label: string;
  className?: string;
}

const HOP = 520;

/** Breadth-first levels from the source: who is reached at each hop. */
function levelsFrom(source: string, edges: [string, string][]) {
  const seen = new Set([source]);
  const levels: string[][] = [[source]];
  while (true) {
    const next: string[] = [];
    for (const id of levels[levels.length - 1])
      for (const [a, b] of edges) {
        const other = a === id ? b : b === id ? a : null;
        if (other && !seen.has(other)) {
          seen.add(other);
          next.push(other);
        }
      }
    if (next.length === 0) return levels;
    levels.push(next);
  }
}

/**
 * Sends a pulse out from one node along every edge, a hop at a time. Each
 * node rings when the pulse reaches it. `onComplete` reports the order, so
 * you can describe the result in words.
 */
export function NodePulseGraph({
  nodes,
  edges,
  source,
  run,
  onComplete,
  viewBox,
  label,
  className = '',
}: NodePulseGraphProps) {
  const reduced = useReducedMotion();
  const levels = useMemo(() => levelsFrom(source, edges), [source, edges]);
  const [t, setT] = useState(-1);
  const byId = useMemo(
    () => Object.fromEntries(nodes.map((n) => [n.id, n])),
    [nodes]
  );
  const depth = useMemo(() => {
    const map: Record<string, number> = {};
    levels.forEach((level, i) => level.forEach((id) => (map[id] = i)));
    return map;
  }, [levels]);

  useEffect(() => {
    if (!run) return;
    const total = (levels.length - 1) * HOP;
    if (reduced) {
      setT(total);
      onComplete?.(levels);
      return;
    }
    let frame = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const elapsed = now - start;
      setT(Math.min(elapsed, total));
      if (elapsed < total) frame = requestAnimationFrame(tick);
      else onComplete?.(levels);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
    // onComplete is a callback; a new pulse starts only when `run` changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run, levels, reduced]);

  const hop = t < 0 ? -1 : t / HOP;
  const pulses = edges.flatMap(([a, b]) => {
    const [from, to] = depth[a] < depth[b] ? [a, b] : [b, a];
    if (depth[to] !== depth[from] + 1) return [];
    const local = hop - depth[from];
    if (local <= 0 || local >= 1) return [];
    const p = byId[from];
    const q = byId[to];
    return [
      {
        key: `${from}-${to}`,
        x: p.x + (q.x - p.x) * local,
        y: p.y + (q.y - p.y) * local,
      },
    ];
  });

  return (
    <svg
      className={`mg-pulse ${className}`}
      viewBox={viewBox}
      role='img'
      aria-label={label}
    >
      {edges.map(([a, b]) => (
        <line
          key={`${a}-${b}`}
          className='mg-pulse__edge'
          x1={byId[a].x}
          y1={byId[a].y}
          x2={byId[b].x}
          y2={byId[b].y}
        />
      ))}
      {nodes.map((node) => {
        const reached = hop >= 0 && hop >= (depth[node.id] ?? Infinity);
        return (
          <g
            key={node.id}
            className='mg-pulse__node'
            data-reached={reached}
            data-source={node.id === source}
          >
            <circle className='mg-pulse__ring' cx={node.x} cy={node.y} r='16' />
            <circle className='mg-pulse__dot' cx={node.x} cy={node.y} r='9' />
            <text x={node.x} y={node.y + 26} textAnchor='middle'>
              {node.label}
            </text>
          </g>
        );
      })}
      {pulses.map((p) => (
        <circle
          key={p.key}
          className='mg-pulse__spark'
          cx={p.x}
          cy={p.y}
          r='5'
        />
      ))}
    </svg>
  );
}

.mg-pulse {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

.mg-pulse__edge {
  stroke: #303030;
  stroke-width: 2;
}

.mg-pulse__dot {
  fill: #121212;
  stroke: #5c5c5c;
  stroke-width: 2;
  transition:
    fill 200ms ease,
    stroke 200ms ease;
}

.mg-pulse__ring {
  fill: none;
  stroke: var(--mg-accent-text, #dce9f7);
  stroke-width: 3;
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.mg-pulse__node[data-reached='true'] .mg-pulse__dot {
  fill: var(--mg-accent, #eaf2fb);
  stroke: var(--mg-text, #ffffff);
}

.mg-pulse__node[data-reached='true'] .mg-pulse__ring {
  animation: mg-pulse-ring 600ms ease-out;
}

/* The source node is drawn as a square-ish badge so it differs by shape too. */
.mg-pulse__node[data-source='true'] .mg-pulse__dot {
  stroke-width: 4;
}

.mg-pulse__node text {
  fill: var(--mg-text, #ffffff);
  font-size: 11px;
  font-weight: 600;
}

.mg-pulse__spark {
  fill: var(--mg-accent, #eaf2fb);
  stroke: var(--mg-text, #ffffff);
  stroke-width: 1.5;
}

@keyframes mg-pulse-ring {
  from {
    opacity: 1;
    transform: scale(0.6);
  }
  to {
    opacity: 0;
    transform: scale(1.6);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-pulse__dot {
    transition: none;
  }
  .mg-pulse__node[data-reached='true'] .mg-pulse__ring {
    animation: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
